#!/usr/bin/env bash
# Run 2026-08-07-sr1-best-popqa, generated by exp.py from configs/sr1_popqa_best.yaml.
# Written before any stage starts, so the run stays reproducible even if
# the process is killed.
set -euo pipefail
cd /path/to/repo

CUDA_VISIBLE_DEVICES=0 HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1 \
  /path/to/venv/bin/python fullwiki_qrag.py search --index-dir /path/to/data/full-wiki/wiki18-gte --qrag-repo /path/to/repo/Q-RAG_for_full-wiki --device cuda:0 --model-dtype float32 --input /path/to/repo/runs/shared/searchr1/popqa.jsonl --output /path/to/repo/runs/2026-08-07-sr1-best-popqa/retrieval.jsonl --batch-size 64 --top-k 100 --steps 6 --max-chunks-per-title 2 --log-candidates none --checkpoint /path/to/repo/Q-RAG_for_full-wiki/runs/Aug03_12-44-38_lineA_main/model_best.pt --state-source critic --no-auto-prepare

# judge: 32 shards of answer_judge_llms.py, then merged
# /path/to/venv/bin/python /path/to/Q-RAG-feedback/answer_judge_llms.py --retriever-logfile <shard>.jsonl --output-file <shard>.json --base-url http://127.0.0.1:8010/v1 --answer-model Qwen3-4B --max-samples 100000 --max-tokens 1000 --judge-max-tokens 100

python exp.py run --config configs/sr1_popqa_best.yaml --only score
